import React, { useState } from 'react';
import axios from 'axios';

const StepForm = ({ onAddStep, vehicles }) => {
  const [stepType, setStepType] = useState('');
  const [vehicleIndex, setVehicleIndex] = useState(0);
  const [stationIndex, setStationIndex] = useState(0);
  const [stepData, setStepData] = useState({
    chargeInfo: '',
    dischargeInfo: '',
    tripInfo: ''
  });

  const handleStepTypeChange = (e) => {
    setStepType(e.target.value);
  };

  const handleVehicleChange = (e) => {
    setVehicleIndex(e.target.value);
  };

  const handleStationChange = (e) => {
    setStationIndex(e.target.value);
  };

  const handleChange = (e) => {
    setStepData({
      ...stepData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const dataToSubmit = {
      stepType,
      vehicle: vehicles[vehicleIndex].name,
      ...stepData
    };
    onAddStep(dataToSubmit);
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Select Vehicle:
        <select value={vehicleIndex} onChange={handleVehicleChange}>
          {vehicles.map((vehicle, index) => (
            <option key={index} value={index}>{vehicle.name}</option>
          ))}
        </select>
      </label>

      <label>
        Step Type:
        <select value={stepType} onChange={handleStepTypeChange}>
          <option value="">Select Step Type</option>
          <option value="charge">Charge</option>
          <option value="discharge">Discharge</option>
          <option value="trip">Trip</option>
        </select>
      </label>

      {stepType === 'charge' && (
        <div>
        <label>
          Select station:
          <select value={stationIndex} onChange={handleStationChange}>
            {stations.map((station, index) => (
              <option key={index} value={index}>{station.name}</option>
            ))}
          </select>
        </label>
          <label>
            Start charge:
            <input
              type="number"
              name="start_charge"
              value={stepData.start_charge}
              onChange={handleChange}
            />
          </label>
          <label>
            End charge:
            <input
              type="number"
              name="end_charge"
              value={stepData.end_charge}
              onChange={handleChange}
            />
          </label>
          <label>
            Desired charge:
            <input
              type="number"
              name="desired_charge"
              value={stepData.desired_charge}
              onChange={handleChange}
            />
          </label>
        </div>
      )}

      {stepType === 'discharge' && (
        <div>
          <label>
            Station:
            <input
              type="text"
              name="station"
              value={stepData.station}
              onChange={handleChange}
            />
          </label>
          <label>
            Start discharge:
            <input
              type="number"
              name="start_discharge"
              value={stepData.start_discharge}
              onChange={handleChange}
            />
          </label>
          <label>
            duration:
            <input
              type="number"
              name="duration"
              value={stepData.duration}
              onChange={handleChange}
            />
          </label>
        </div>
      )}

      {stepType === 'trip' && (
        <div>
          <label>
            Start trip:
            <input
              type="text"
              name="start_trip"
              value={stepData.start_trip}
              onChange={handleChange}
            />
          </label>
          <label>
            End trip:
            <input
              type="number"
              name="end_trip"
              value={stepData.end_trip}
              onChange={handleChange}
            />
          </label>
          <label>
            Destination:
            <input
              type="numbers"
              name="destination"
              value={stepData.destination}
              onChange={handleChange}
            />
          </label>
        </div>
      )}

      <button type="submit">Add Step</button>
    </form>
  );
};

export default StepForm;
